fn decode_shift(s: Vec<char>) -> Vec<char> {
    // Pre-allocate the output vector with the same length as the input.
    let mut t = Vec::with_capacity(s.len());

    for c in s {
        // Convert from 'a'..'z' to 0..25
        let alpha_index = c as u8 - b'a';
        // Left shift by 5 with wrap-around modulo 26
        let shifted = (alpha_index + 26 - 5) % 26;
        // Convert back to 'a'..'z'
        let decoded = (b'a' + shifted) as char;
        t.push(decoded);
    }

    t
}

